import heapq


def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best = None
        best_ids = None

        for chosen in __import__("itertools").combinations(jobs, k):
            ids = {job["id"] for job in chosen}
            if ids & blocked or not mandatory <= ids:
                continue
            counts = {}
            for job in chosen:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            events = []
            for job in chosen:
                events.append((job["start"], 1))
                events.append((job["end"], -1))
            active = 0
            feasible = True
            for _, delta in sorted(events, key=lambda event: (event[0], event[1])):
                active += delta
                if active > capacity:
                    feasible = False
                    break
            if not feasible:
                continue
            value = sum(job["value"] for job in chosen)
            selected = sorted(ids)
            if (best is None or value > best or
                    (value == best and
                     (selected > best_ids if tie == "largest" else selected < best_ids))):
                best, best_ids = value, selected

        if best is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if ident not in winners or key > winners[ident][0]:
            winners[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    half_up = data["rounding"] == "half_up"

    def rounded(n, d):
        return (n + d // 2) // d if half_up else n // d

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    choices = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name])
        choices.append([-1] + versions)

    for vector in product(*choices):
        selected = {name: version for name, version in zip(names, vector)
                    if version != -1}
        if any(name not in selected or not low <= selected[name] <= high
               for name, (low, high) in roots.items()):
            continue
        if any(name in selected and selected[name] != version
               for name, version in pins.items()):
            continue
        if any(version in blocked.get(name, [])
               for name, version in selected.items()):
            continue

        rows = {}
        valid = True
        edges = {}
        for name, version in selected.items():
            row = next((r for r in packages[name] if r["version"] == version), None)
            if row is None:
                valid = False
                break
            rows[name] = row
            active = [dep for dep in row.get("deps", [])
                      if not dep.get("feature") or dep["feature"] in features]
            edges[name] = []
            for dep in active:
                other = dep["name"]
                edges[name].append(other)
                if (other not in selected or
                        not dep["min"] <= selected[other] <= dep["max"]):
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue

        # The installed set must be exactly the closure reachable from roots.
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            if name not in selected:
                valid = False
                break
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if not valid or reachable != set(selected):
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for other in edges.get(name, []):
                if not visit(other):
                    return False
            state[name] = 2
            return True
        if not all(visit(name) for name in selected):
            continue
        return {"versions": selected}
    return {"error": "unsatisfiable"}


def _routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit.get(data["source"], 0)
    start_state = (data["source"], initial_mask, data["coupons"])
    start_time = data["start"]
    dist = {start_state: start_time}
    queue = [(start_time, data["source"], initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bit.get(nxt, 0)
                next_state = (nxt, next_mask, left)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, left))
    return {"arrival": None}


